`timescale 10 ps / 1 ps

module PH1P_PHY_HD_PAD (
        ipad,
        opad,
        bpad,
        rst,
        ce,
        ipclk,
        osclk,
        ts,
        doq,
        di,
        diq,
        dly_in,
        dly_out,
        dly_src_sel,
        dly,
        lb_enb,
        in_dl_through,
        out_dl_through,
        in_dl_return,
        out_dl_return
);
input            dly_in;
input            dly_src_sel;    //"0":sdl32_in_clk ; "1":pib_bist_in
input            in_dl_through;  //[tag:hardwire]
input            in_dl_return;   //[tag:hardwire]
output           out_dl_through; //[tag:hardwire]
output           out_dl_return;  //[tag:hardwire]
output           dly_out;
input            ipad;           //[tag:virtual]
output           opad;           //[tag:virtual]
inout            bpad;           //[tag:virtual]
input            rst;            //[tag:reset]
input            ce;
input            ipclk;          //[tag:clk]
input            osclk;          //[tag:clk]
input            ts;
input            lb_enb;
input  [1:0]     doq;
output           di;
output [1:0]     diq;
input  [4:0]     dly;

tri1            rst;
tri1            ce;
tri1            ipclk;
tri1            osclk;
tri1            ts;
tri1  [1:0]     doq;
tri1  [4:0]     dly;
tri1            lb_enb;

//////////////////////////////////////IOL/////////////////////////////////////////////////////

//iddr
parameter IPCLKSWI          = "SIG";            // "SIG", "INV" : [mc1_ick_sel]
parameter IDDRMODE          = "BYPASS";         // "BYPASS", "SDR", "DDRX1_OPPOSITE", "DDRX1_SAME_EDGE", "DDRX1_SAME_EDGE_PIPE" :[mc1_ix2_opposite,mc1_ix2_same_edge]
parameter DI_SEL            = "SIG";            // "SIG", "INV", "0", "1" : [mc1_di_sel]
parameter INCKEN            = "DISABLE";        // "ENABLE", "DISABLE" : [mc1_do_sel_sclk]
parameter IN_REGSET         = "RESET";          // "RESET", "SET" : [mc1_i_set]
parameter DI_TEST           = "DO";             // "DI", "DO" : [mc1_di_mode]
//oddr
parameter OSCLKSWI          = "SIG";            // "SIG", "INV" : [mc1_ock_sel]
parameter DOQ0MUX           = "SIG";            // "SIG", "INV", "0", "1" : [mc1_d0_sel]
parameter DOQ1MUX           = "SIG";            // "SIG", "INV", "0", "1" : [mc1_d1_sel]  
parameter ODDRMODE          = "BYPASS";         // "BYPASS", "SDR", "DDRX1" : [mc1_osdr,mc1_ock_dly_mode]
parameter OTYPE             = "DIRECTD0";       // "DIRECTD0", "TEST" ,"DDRSDR" : [iol_mc1_do_sel]
parameter OUT_REGSET        = "RESET";          // "RESET", "SET" : [mc1_o_set]
parameter TESTSEL           = "PREVIO";         // "PREVIO", "OCLK" : [mc1_prev_inck_sel]
//ts 
parameter TSMUX             = "SIG";            // "SIG", "INV", "0", "1"  : [mc1_ts_mode]
parameter TSMODE            = "NONE";           // "NONE", "SDFF" : [mc1_ts_sel]
parameter TS_REGSET         = "RESET";          // "RESET", "SET" : [mc1_ts_set]
//reset
parameter INRST             = "DISABLE";        // "ENABLE", "DISABLE" : [mc1_inrst_en]
parameter OUTRST            = "DISABLE";        // "ENABLE", "DISABLE" : [mc1_outrst_en]
parameter GSR               = "ENABLE";         // "ENABLE", "DISABLE" : [mc1_dis_gsr]
parameter SRMODE            = "SYNC";           // "ASYNC", "SYNC" : [mc1_rst_asyn]
parameter RSTMUX            = "RST";            // "RST", "INV" : [mc1_rst_inv]
//ce
parameter INCE              = "PROGCE";         // "1", "PROGCE"  : [mc1_ince_en]
parameter OUTCE             = "PROGCE";         // "1", "PROGCE"  : [mc1_outce_en]
parameter CEMUX             = "CE";             // "CE", "INV"    : [mc1_ce_inv]
//dly
parameter IPCLK_DLY         = "DISABLE";        // "ENABLE", "DISABLE" : [mc1_ick_dly_mode]
parameter IDLYEN            = "DISABLE";        // "DISABLE", "ENABLE" : [mc1_indly]
parameter ODLYEN            = "DISABLE";        // "DISABLE", "ENABLE" : [iol_mc1_do_sel]   
parameter DLYSRC            = "IOB";            // "IOB", "ODDR": [mc1_sdl32_clk_sel]
parameter DLYCASSRC         = "CASCADE";        // "CASCADE", "SOFT" : [mc1_cas_out_src]
parameter DLYCAS_MODE       = "NONE";           // "MASTER", "MIDDLE", "END", "NONE" : [mc1_dly_rtn_out_src,mc1_cas_in_src,mc1_cas_gate,mc1_dly_in_src]


//////////////////////////////////////IOL/////////////////////////////////////////////////////

//////////////////////////////////////IOB/////////////////////////////////////////////////////
parameter MODE               = "IN";            // "NONE", "IN", "OUT", "BI" : [mc1_rx_mode,mc1_ensrc,mc1_ensnk,mc1_do_sel,mc1_slew]
parameter IOTYPE             = "LVCMOS18";      // "LVTTL33","LVCMOS33" , "LVCMOS25" , "LVCMOS18" , "LVCMOS15", "LVDS33_E", "LVDS25_E", "LVDS18_E" :[mc1_rx_mode,mc1_ensrc,mc1_ensnk,mc1_slew]
//parameter DRIVE              = "8";            //"NONE" , "4" , "8" , "12" ,"16": [mc1_ensrc,mc1_ensnk]
//parameter SLEWRATE           = "SLOW";         //"SLOW", "MED", "FAST":[mc1_slew]
//parameter PULLMODE           = "NONE" ;        // "PULLUP" , "PULLDOWN" , "NONE" , "KEEPER" : [mc1_usr_pd,mc1_usr_pu_n]
//parameter LVDSE_EN           = "DISABLE";      // "ENABLE" , "DISABLE" : [mc1_do_sel]
//parameter CFG_IN_EN          = "DISABLE";      // "ENABLE", "DISABLE":[mc1_cfg_i_en]
//parameter PWRGUARD           = "DISABLE";      // "ENABLE", "DISABLE":[mc1_pwrgurd_en]

